// 具名授权/军事投影仍为组件输入；关店真正复用原Common recipe、原余额重放与末ID整候选回滚。
#define PRIVATE_SHOP_LIQUIDATION_FIXTURE_ONLY
#include "private_shop_liquidation_test.cpp"
#undef PRIVATE_SHOP_LIQUIDATION_FIXTURE_ONLY
#include "../../../src/resident/domains/commerce/liquidation/private_shop_liquidation_codec.hpp"
#include "resident/domains/tasks/shop_orders/task_shop_asset_responsibilities.hpp"
namespace {
struct EstateTasks:TaskPrivateShopAssetResponsibilityRead {
    const CommonStore* common=nullptr;bool pending=false,fail_history=false;mutable bool saw_cash_return=false;
    Outcome<TaskPrivateShopAssetResponsibilities> current(const TaskPrivateShopAssetScope& scope)const override{return {true,{common->state().identity,scope,common->tick(),{},pending?std::vector<StableId>{"original.pending"}:std::vector<StableId>{}},{}};}
    Outcome<TaskPrivateShopAssetResponsibilities> before_close(const TaskPrivateShopAssetScope& scope,const StableId& fact,Integer tick)const override{saw_cash_return=common->wallet(scope.wallet_id)->balance==0;if(fail_history)return {false,{},common_failure("InjectedEstateClosingHistoryFailure").error};auto out=current(scope);out.value.closing_fact_id=fact;out.value.as_of_tick=tick;return out;}
};
struct ClosingEstate:EstateFixture {
    EstateTasks tasks;DeliveredTaskDeathNotice notice;PrivateShopEstateClose command;
    ClosingEstate(){tasks.common=&common;auto q=appoint();check(q.ok,"predeath appointment");auto accepted=apply(q.value);check(accepted.ok,"predeath original two facts");death();auto ctx=authorization();auto recorded=record_family_death(common,deaths,ctx.death_origin,"owner");check(recorded.ok,"registered original death");auto source=common.next_id("task_death_notice_bound");check(source.ok&&common.append_fact({source.value,"task_death_notice_bound","tasks"}).ok,"original notice binding");auto handoff=common.next_id("task_message_handoff");check(handoff.ok&&common.append_fact({handoff.value,"task_message_handoff","tasks"}).ok,"original delivered notice");notice={common.state().identity,common.state().metadata.scenario_id,source.value,"notice.task","notice.lot",handoff.value,recorded.value,"owner","witness","lessor",0,0};notice_read=[this](const StableId& observer,const StableId& binding)->Outcome<std::optional<DeliveredTaskDeathNotice>>{if(observer!="lessor"||binding!=notice.binding_fact_id)return {true,std::nullopt,{}};auto copy=notice;copy.identity=common.state().identity;return {true,std::move(copy),{}};};command={shop_id,accepted.value.mandate_fact_id,source.value};}
    PrivateShopContext shop_context(){auto x=context();x.closing_tasks=&tasks;return x;}
    Outcome<PrivateShopEstateClosingQuote> closing_quote(){return preview_private_shop_estate_closing(shop_context(),authorization(),"lessor",command);}
    Outcome<StableId> close(const PrivateShopEstateClosingQuote& quote){auto shops=shop_context();auto estate=authorization();local_economy_detail::PhaseSavepoint outer(common);if(!outer.token().ok)return {false,{},outer.token().error};local_economy_detail::CandidateStateGuard<PrivateShopState> guard(state);local_economy_detail::CandidateStateGuard<PrivateShopLiquidationState> law(mandates);auto result=close_private_shop_estate_in_candidate(common,state,mandates,shops,estate,quote);if(!result.ok)return result;auto committed=outer.commit();if(!committed.ok)return {false,{},committed.error};guard.commit();law.commit();return result;}
};
void exact_estate_return(){
    ClosingEstate f;auto q=f.closing_quote();check(q.ok&&q.value.assets.actor_id=="owner"&&q.value.actor_id=="lessor","executor is not estate asset owner");check(!preview_private_shop_closing(f.shop_context(),"owner",{f.shop_id}).ok,"old proprietor command remains unavailable after death");const auto cash=f.common.wallet("owner.wallet")->balance,executor_cash=f.common.wallet("lessor.wallet")->balance;auto done=f.close(q.value);check(done.ok&&f.tasks.saw_cash_return,"same original recipe then historical authority");check(f.common.wallet("owner.wallet")->balance==cash+300&&f.common.wallet("lessor.wallet")->balance==executor_cash&&f.common.wallet(f.state.shops.find(f.shop_id)->wallet_id)->balance==0,"cash returns only deceased original private wallet");check(f.state.closings.size()==1&&f.mandates.closings.size()==1,"original asset closing and executor receipt both permanent");check(validate_private_shop_estate_closings(f.shop_context(),f.authorization()).ok,"joined estate history validates");check(!f.closing_quote().ok,"no repeat business closing");auto raw=encode_private_shop_liquidations(f.mandates);check(decode_private_shop_liquidations(raw).ok,"independent populated estate state format");check(!validate_private_shop_liquidation_layout(f.common,nullptr).ok,"disabled estate module rejects its real Common sources");auto saved=f.mandates;f.mandates.closings.erase(done.value);f.common.state().facts.erase(done.value);check(!validate_private_shop_estate_closings(f.shop_context(),f.authorization()).ok,"removing estate receipt cannot hide death-time asset disposal");f.mandates=saved;
}
void estate_failures_restore_everything(){
    ClosingEstate f;f.tasks.pending=true;check(!f.closing_quote().ok,"original Task obligation still blocks executor");f.tasks.pending=false;auto q=f.closing_quote();check(q.ok,"actual authorized close quote");auto forged=q.value;forged.assets.to_wallet_id="lessor.wallet";const auto snapshot=encode_common_state(f.common.state());check(!f.close(forged).ok&&compare_boundary(snapshot,encode_common_state(f.common.state())).exact(),"executor cannot redirect quoted return");
    f.tasks.fail_history=true;auto shops=encode_private_shop_state(f.state),authority=encode_private_shop_liquidations(f.mandates);auto failed=f.close(q.value);check(!failed.ok&&f.tasks.saw_cash_return,"late source failure observes original money already returned");check(compare_boundary(snapshot,encode_common_state(f.common.state())).exact()&&compare_boundary(shops,encode_private_shop_state(f.state)).exact()&&compare_boundary(authority,encode_private_shop_liquidations(f.mandates)).exact(),"late error restores Common, original Shop, and estate sidecar");f.tasks.fail_history=false;
    f.common.state().next_instance_id=std::numeric_limits<Integer>::max()-1;q=f.closing_quote();check(q.ok,"estate last-ID quotation");auto high=encode_common_state(f.common.state());failed=f.close(q.value);check(!failed.ok&&compare_boundary(high,encode_common_state(f.common.state())).exact()&&f.state.closings.empty()&&f.mandates.closings.empty(),"estate receipt ID failure after old closing returns entire candidate");
}
}
int main(){try{exact_estate_return();estate_failures_restore_everything();std::cout<<checks<<"/0 isolated estate return checks\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
